import{_ as s,a,c as t,ac as i}from"./chunks/framework.BSuaGltH.js";const w=JSON.parse('{"title":"第一册：英语初阶 · 综合复习与自测 · 第137–143课","description":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","frontmatter":{"title":"第一册：英语初阶 · 综合复习与自测 · 第137–143课","description":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","splitFrom":"life/english/new-concept/book-1/review.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"读写与对话练习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第一册：英语初阶 · 综合复习与自测","summary":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · 综合复习与自测 · 第130–136课","link":"/life/english/new-concept/book-1/review-part-19"},"next":{"text":"第一册：英语初阶 · 综合复习与自测 · 第144课","link":"/life/english/new-concept/book-1/review-part-21"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · 综合复习与自测 · 第130–136课","link":"/life/english/new-concept/book-1/review-part-19"},"next":{"text":"第一册：英语初阶 · 综合复习与自测 · 第144课","link":"/life/english/new-concept/book-1/review-part-21"}},"headers":[],"relativePath":"life/english/new-concept/book-1/review-part-20.md","filePath":"life/english/new-concept/book-1/review-part-20.md"}'),o={name:"life/english/new-concept/book-1/review-part-20.md"};function l(n,e,r,h,p,c){return a(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="第一册-英语初阶-·-综合复习与自测-·-第137–143课" tabindex="-1">第一册：英语初阶 · 综合复习与自测 · 第137–143课 <a class="header-anchor" href="#第一册-英语初阶-·-综合复习与自测-·-第137–143课" aria-label="Permalink to &quot;第一册：英语初阶 · 综合复习与自测 · 第137–143课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-1/review">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-1/overview">本册介绍</a> · <a href="/life/english/new-concept/book-1/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-1/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-1/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-1/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-1/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-1/review">综合复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="lesson-137-·-真实条件句" tabindex="-1">Lesson 137 · 真实条件句 <a class="header-anchor" href="#lesson-137-·-真实条件句" aria-label="Permalink to &quot;Lesson 137 · 真实条件句 {#lesson-137-·-真实条件句}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> If we finish early, we will take a walk.</p><h3 id="练习-1-136" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-136" aria-label="Permalink to &quot;练习 1 {#练习-1-136}&quot;">​</a></h3><p>填动词：If it ___ (rain), we will stay inside.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> rains</p><p><strong>解析：</strong> 按本课规则判断：表达未来可能实现的条件时，常用 if + 一般现在时，主句 will + 原形。if 从句不是已经发生，而是条件；主句也不是绝对保证，而是条件成立时的结果。从句放前面通常用逗号分隔，放后面通常不需要。不要因条件指未来就在普通 if 条件从句中机械加 will。</p></details><p><strong>表达迁移：</strong> 围绕“设想有可能发生的未来条件”写两至三句，再读给同伴听。至少使用一次真实条件句，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>If we finish early, we will take a walk. We will stay indoors if it rains tomorrow.</p><p>If we finish early 为条件，用一般现在时；we will take a walk 为条件成立后的结果，用 will 加原形。 主句 will stay 表结果，后置 if it rains tomorrow 表未来条件；rains 用现在时，不机械改 will rain。</p></details><p><a href="/life/english/new-concept/book-1/unit-06/lesson-137">回看本课</a></p><h2 id="lesson-138-·-真实条件句" tabindex="-1">Lesson 138 · 真实条件句 <a class="header-anchor" href="#lesson-138-·-真实条件句" aria-label="Permalink to &quot;Lesson 138 · 真实条件句 {#lesson-138-·-真实条件句}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> We will stay indoors if it rains tomorrow.</p><h3 id="练习-1-137" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-137" aria-label="Permalink to &quot;练习 1 {#练习-1-137}&quot;">​</a></h3><p>填主句：If we finish early, we ___ take a walk.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> will</p><p><strong>解析：</strong> 按本课规则判断：表达未来可能实现的条件时，常用 if + 一般现在时，主句 will + 原形。if 从句不是已经发生，而是条件；主句也不是绝对保证，而是条件成立时的结果。从句放前面通常用逗号分隔，放后面通常不需要。不要因条件指未来就在普通 if 条件从句中机械加 will。</p></details><p><strong>表达迁移：</strong> 围绕“设想有可能发生的未来条件”写两至三句，再读给同伴听。至少使用一次真实条件句，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>We will stay indoors if it rains tomorrow. If we finish early, we will take a walk.</p><p>主句 will stay 表结果，后置 if it rains tomorrow 表未来条件；rains 用现在时，不机械改 will rain。 If we finish early 为条件，用一般现在时；we will take a walk 为条件成立后的结果，用 will 加原形。</p></details><p><a href="/life/english/new-concept/book-1/unit-06/lesson-138">回看本课</a></p><h2 id="lesson-139-·-间接疑问句的陈述语序" tabindex="-1">Lesson 139 · 间接疑问句的陈述语序 <a class="header-anchor" href="#lesson-139-·-间接疑问句的陈述语序" aria-label="Permalink to &quot;Lesson 139 · 间接疑问句的陈述语序 {#lesson-139-·-间接疑问句的陈述语序}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> She wants to know whether the office is open.</p><h3 id="练习-1-138" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-138" aria-label="Permalink to &quot;练习 1 {#练习-1-138}&quot;">​</a></h3><p>排序：know / where / he / lives（I 开头）.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> I know where he lives.</p><p><strong>解析：</strong> 按本课规则判断：宾语从句中的疑问内容采用陈述语序：know where he lives，而非 know where does he live。一般疑问内容可用 if/whether 表“是否”；这里的 if 不表示条件。转述时去掉原问句帮助倒装的 do/does/did，但把所需时态保留在从句谓语。礼貌问句外层可以倒装，内层仍用陈述语序。</p></details><p><strong>表达迁移：</strong> 围绕“转述电话里提出的问题”写两至三句，再读给同伴听。至少使用一次间接疑问句的陈述语序，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>She wants to know whether the office is open. Could you tell me when the meeting starts?</p><p>Wants to know 是主句谓语结构；whether 表“是否”，从句 the office is open 采用陈述语序。 Could you tell me 是外层礼貌问句；内层 when the meeting starts 是间接疑问，不能再加 does 倒装。</p></details><p><a href="/life/english/new-concept/book-1/unit-06/lesson-139">回看本课</a></p><h2 id="lesson-140-·-间接疑问句的陈述语序" tabindex="-1">Lesson 140 · 间接疑问句的陈述语序 <a class="header-anchor" href="#lesson-140-·-间接疑问句的陈述语序" aria-label="Permalink to &quot;Lesson 140 · 间接疑问句的陈述语序 {#lesson-140-·-间接疑问句的陈述语序}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Could you tell me when the meeting starts?</p><h3 id="练习-1-139" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-139" aria-label="Permalink to &quot;练习 1 {#练习-1-139}&quot;">​</a></h3><p>补“是否”：She asks ___ the office is open.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> if / whether</p><p><strong>解析：</strong> 按本课规则判断：宾语从句中的疑问内容采用陈述语序：know where he lives，而非 know where does he live。一般疑问内容可用 if/whether 表“是否”；这里的 if 不表示条件。转述时去掉原问句帮助倒装的 do/does/did，但把所需时态保留在从句谓语。礼貌问句外层可以倒装，内层仍用陈述语序。</p></details><p><strong>表达迁移：</strong> 围绕“转述电话里提出的问题”写两至三句，再读给同伴听。至少使用一次间接疑问句的陈述语序，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Could you tell me when the meeting starts? She wants to know whether the office is open.</p><p>Could you tell me 是外层礼貌问句；内层 when the meeting starts 是间接疑问，不能再加 does 倒装。 Wants to know 是主句谓语结构；whether 表“是否”，从句 the office is open 采用陈述语序。</p></details><p><a href="/life/english/new-concept/book-1/unit-06/lesson-140">回看本课</a></p><h2 id="lesson-141-·-一般过去时被动语态" tabindex="-1">Lesson 141 · 一般过去时被动语态 <a class="header-anchor" href="#lesson-141-·-一般过去时被动语态" aria-label="Permalink to &quot;Lesson 141 · 一般过去时被动语态 {#lesson-141-·-一般过去时被动语态}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The guests were invited by email.</p><h3 id="练习-1-140" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-140" aria-label="Permalink to &quot;练习 1 {#练习-1-140}&quot;">​</a></h3><p>填 be：The guests ___ invited yesterday.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> were</p><p><strong>解析：</strong> 按本课规则判断：被动语态由 be + 过去分词构成，时态与主谓一致体现在 be 上。一般过去时用 was/were + 分词。只有及物动词及可接受的及物结构通常能转被动，happen 不可机械写 was happened。执行者不重要或未知时，可以省略引出执行者的 by 短语；如 by the host 中 the host 是执行者。by 也可表示方式，如本课 by email 表示通过电子邮件，不能把所有 by 短语都理解为执行者。</p></details><p><strong>表达迁移：</strong> 围绕“把注意力从执行者转向事件对象”写两至三句，再读给同伴听。至少使用一次一般过去时被动语态，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The guests were invited by email. This bridge was built fifty years ago.</p><p>The guests 为被邀请者，were invited 为过去被动；by email 表通过邮件这一方式，并非动作执行者。 This bridge 为动作承受者，was built 为单数过去被动；fifty years ago 为明确过去时间。</p></details><p><a href="/life/english/new-concept/book-1/unit-06/lesson-141">回看本课</a></p><h2 id="lesson-142-·-一般过去时被动语态" tabindex="-1">Lesson 142 · 一般过去时被动语态 <a class="header-anchor" href="#lesson-142-·-一般过去时被动语态" aria-label="Permalink to &quot;Lesson 142 · 一般过去时被动语态 {#lesson-142-·-一般过去时被动语态}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> This bridge was built fifty years ago.</p><h3 id="练习-1-141" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-141" aria-label="Permalink to &quot;练习 1 {#练习-1-141}&quot;">​</a></h3><p>填分词：The bridge was ___ (build) in 1970.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> built</p><p><strong>解析：</strong> 按本课规则判断：被动语态由 be + 过去分词构成，时态与主谓一致体现在 be 上。一般过去时用 was/were + 分词。只有及物动词及可接受的及物结构通常能转被动，happen 不可机械写 was happened。执行者不重要或未知时，可以省略引出执行者的 by 短语；如 by the host 中 the host 是执行者。by 也可表示方式，如本课 by email 表示通过电子邮件，不能把所有 by 短语都理解为执行者。</p></details><p><strong>表达迁移：</strong> 围绕“把注意力从执行者转向事件对象”写两至三句，再读给同伴听。至少使用一次一般过去时被动语态，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>This bridge was built fifty years ago. The guests were invited by email.</p><p>This bridge 为动作承受者，was built 为单数过去被动；fifty years ago 为明确过去时间。 The guests 为被邀请者，were invited 为过去被动；by email 表通过邮件这一方式，并非动作执行者。</p></details><p><a href="/life/english/new-concept/book-1/unit-06/lesson-142">回看本课</a></p><h2 id="lesson-143-·-现在完成时与将来时被动" tabindex="-1">Lesson 143 · 现在完成时与将来时被动 <a class="header-anchor" href="#lesson-143-·-现在完成时与将来时被动" aria-label="Permalink to &quot;Lesson 143 · 现在完成时与将来时被动 {#lesson-143-·-现在完成时与将来时被动}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The path has been cleared of fallen branches.</p><h3 id="练习-1-142" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-142" aria-label="Permalink to &quot;练习 1 {#练习-1-142}&quot;">​</a></h3><p>补 be 的形式：The path has ___ cleared.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> been</p><p><strong>解析：</strong> 按本课规则判断：现在完成时被动为 have/has been + 过去分词，将来时被动为 will be + 过去分词。have/has 仍要与主语一致，been 不可漏；will 后用原形 be，不用 been。先判断是否被动，再判断完成或将来，不能把两种结构拼成 will been。表达“树木已被种下”与“明天将被种下”时，动作对象相同而时间不同。</p></details><p><strong>表达迁移：</strong> 围绕“描述环境变化与待完成的工作”写两至三句，再读给同伴听。至少使用一次现在完成时与将来时被动，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The path has been cleared of fallen branches. New trees will be planted beside the stream.</p><p>The path 是清理对象，has been cleared 为现在完成时被动；of fallen branches 说明被清除的东西。 New trees 是被种植对象，will be planted 为将来时被动；beside the stream 表未来种植位置。</p></details><p><a href="/life/english/new-concept/book-1/unit-06/lesson-143">回看本课</a></p>',60)])])}const m=s(o,[["render",l]]);export{w as __pageData,m as default};
